export function resolveStopStatus(validationState: string | null): RouteStopStatus | "skipped" {
  if (validationState === "cancel") return "skipped";
  if (validationState === "validated") return "completed";
  return "upcoming";
}

export function composeAddress(
  street: string | null,
  street2: string | null,
  zip: string | null,
): string {
  const parts = [street, street2, zip].map((p) => (p ?? "").trim()).filter(Boolean);
  return parts.join(", ");
}

export function formatStopTime(value: string | null): string | null {
  if (!value) return null;
  const normalized = value.includes("T") ? value : value.replace(" ", "T");
  const date = new Date(normalized);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
}

export function formatDistance(meters: number): string {
  if (meters < 1000) return `${Math.round(meters)} m`;
  return `${(meters / 1000).toFixed(1)} km`;
}

export function haversineMeters(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const earth = 6371000;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 2 * earth * Math.asin(Math.sqrt(h));
}

export const PLACEHOLDER_VISIT_TYPE = "Delivery";

export function placeholderEta(index: number): string {
  const base = 11 * 60 + 45;
  const minutes = base + index * 105;
  const hh = Math.floor((minutes / 60) % 24)
    .toString()
    .padStart(2, "0");
  const mm = (minutes % 60).toString().padStart(2, "0");
  return `${hh}:${mm}`;
}
