<template>
  <F7Page class="!bg-transparent [&_.page-content]:!bg-transparent">
    <F7Navbar
      title="Route"
      :subtitle="planningName ?? 'Today\'s itinerary'"
      large
      :sliding="true"
      :class="
        expanded
          ? '[&_.navbar-bg]:!opacity-0 [&_.title]:!opacity-0 [&_.subtitle]:!opacity-0 [&_.title-large]:!opacity-0'
          : ''
      "
    >
      <template #nav-right>
        <div class="flex items-center gap-2 pr-3">
          <F7Link icon-only searchbar-enable=".route-searchbar" class="!w-10 !h-10">
            <span
              class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <ILucideSearch class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
          <F7Link icon-only class="!w-10 !h-10" @click="expanded = !expanded">
            <span
              class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <ILucideMinimize2 v-if="expanded" class="h-[18px] w-[18px] text-ink-soft" />
              <ILucideMaximize2 v-else class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
        </div>
      </template>

      <F7Searchbar
        class="route-searchbar"
        expandable
        :backdrop="false"
        placeholder="Search clients"
        :value="searchTerm"
        @input="searchTerm = ($event.target as HTMLInputElement).value"
        @searchbar:disable="searchTerm = ''"
      />
    </F7Navbar>

    <div class="fixed inset-0 z-0">
      <RouteMap :stops="itinerary.mapStops" @stop-tap="onStopTap" />
    </div>

    <div v-show="!expanded" class="relative z-10">
      <div class="h-[42vh]" @click="onMapTap"></div>
      <div
        class="-mt-6 min-h-[62vh] rounded-t-3xl bg-[#f5f9ff] px-[18px] pb-[120px] pt-3 shadow-[0_-14px_34px_rgba(31,58,107,0.2)] max-[430px]:px-3.5"
      >
        <div class="mx-auto mb-3 h-1.5 w-10 rounded-full bg-[#cdd8ec]"></div>

        <div class="mb-4 flex items-center justify-between">
          <h2 class="text-[17px] font-[820] leading-none text-[#090e24]">Today's visits</h2>
          <F7Link icon-only @click="optimizeRoute">
            <span
              class="glass-surface flex h-9 w-9 min-w-[36px] shrink-0 items-center justify-center rounded-xl"
            >
              <ILucideWandSparkles class="h-[17px] w-[17px] text-[#1f6df5]" />
            </span>
          </F7Link>
        </div>

        <div v-if="loading" class="flex justify-center py-10">
          <F7Preloader />
        </div>

        <p v-else-if="isEmpty" class="py-10 text-center text-sm font-[540] text-[#657096]">
          No stops planned for today.
        </p>

        <template v-else>
          <RouteCurrentStopCard
            v-if="itinerary.currentStop"
            :name="itinerary.currentStop.name"
            :address="itinerary.currentStop.address"
            :image-src="partnerImageSrc(itinerary.currentStop.image)"
            :distance-label="distanceLabel"
            :visit-type="PLACEHOLDER_VISIT_TYPE"
          />

          <section v-if="itinerary.upcoming.length" class="mt-6">
            <h2 class="mb-3 text-[16px] font-[820] leading-none text-[#090e24]">Upcoming</h2>
            <div class="flex flex-col gap-2.5">
              <RouteStopRow
                v-for="(stop, index) in itinerary.upcoming"
                :key="stop.ruid"
                :name="stop.name"
                :address="stop.address"
                :image-src="partnerImageSrc(stop.image)"
                :time="placeholderEta(index)"
                variant="upcoming"
                @open="onStopTap(stop.sequence)"
              />
            </div>
          </section>

          <section v-if="itinerary.completed.length" class="mt-6">
            <h2 class="mb-3 text-[16px] font-[820] leading-none text-[#090e24]">Completed</h2>
            <div class="flex flex-col gap-2.5">
              <RouteStopRow
                v-for="stop in itinerary.completed"
                :key="stop.ruid"
                :name="stop.name"
                :address="stop.address"
                :image-src="partnerImageSrc(stop.image)"
                :time="stop.timeLabel"
                variant="completed"
                @open="onStopTap(stop.sequence)"
              />
            </div>
          </section>
        </template>
      </div>
    </div>
  </F7Page>
</template>

<script setup lang="ts">
import RouteMap from "../components/RouteMap.vue";
import RouteCurrentStopCard from "../components/RouteCurrentStopCard.vue";
import RouteStopRow from "../components/RouteStopRow.vue";
import { useRouteItinerary } from "../composables/useRouteItinerary";
import { useDeviceLocation } from "../composables/useDeviceLocation";
import {
  formatDistance,
  haversineMeters,
  placeholderEta,
  PLACEHOLDER_VISIT_TYPE,
} from "../route.format";
import { partnerImageSrc } from "../route.visuals";

const { itinerary, planningName, searchTerm, loading, isEmpty } = useRouteItinerary();
const { coords } = useDeviceLocation();

const expanded = ref(false);

let lastTapAt = 0;
function onMapTap() {
  const now = performance.now();
  if (now - lastTapAt < 320) {
    expanded.value = true;
    lastTapAt = 0;
  } else {
    lastTapAt = now;
  }
}

watch(expanded, (value) => {
  if (value) f7.toolbar.hide(".tabbar");
  else f7.toolbar.show(".tabbar");
});

onBeforeUnmount(() => f7.toolbar.show(".tabbar"));

const distanceLabel = computed(() => {
  const stop = itinerary.value.currentStop;
  if (!stop || stop.lat == null || stop.lng == null || !coords.value) return null;
  return formatDistance(haversineMeters(coords.value, { lat: stop.lat, lng: stop.lng }));
});

function onStopTap(sequence: number) {
  void sequence;
}

function optimizeRoute() {
  f7.toast.create({ text: "Route optimization coming soon", closeTimeout: 2000 }).open();
}
</script>
